def compute_output(grid, seeds, seeds_as=2):
    """Compute output grid based on distance rule"""
    rows, cols = len(grid), len(grid[0])
    all_1 = [(r,c) for r in range(rows) for c in range(cols) if grid[r][c] == 1]

    output = [[0]*cols for _ in range(rows)]

    # Compute distances
    def d_to_seeds(pos):
        return min(abs(pos[0]-s[0]) + abs(pos[1]-s[1]) for s in seeds)

    def d_to_1s(pos):
        if pos in all_1:
            return 0
        return min(abs(pos[0]-t[0]) + abs(pos[1]-t[1]) for t in all_1)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:  # 1 stays 1
                output[r][c] = 1
            else:  # 0 (or 2 in input) becomes 2 if d_seed <= d_1
                ds = d_to_seeds((r,c))
                d1 = d_to_1s((r,c))
                if ds <= d1:
                    output[r][c] = seeds_as
                # else stays 0

    return output

