from collections import deque

def check_line_of_sight(start_pos, target_pos, grid):
    """Check if there's a straight-line path (horizontal or vertical) from start to target, blocked by 1s"""
    i1, j1 = start_pos
    i2, j2 = target_pos

    # Vertical line
    if i1 == i2:
        cols = range(min(j1, j2), max(j1, j2) + 1)
        for j in cols:
            if j != j2 and grid[i1][j] == 1:
                return False
        return True

    # Horizontal line
    if j1 == j2:
        rows = range(min(i1, i2), max(i1, i2) + 1)
        for i in rows:
            if i != i2 and grid[i][j1] == 1:
                return False
        return True

    return False

def check_any_line_of_sight(start_pos, target_positions, grid):
    """Check if there's any unblocked line of sight (straight horizontal or vertical) from start to target"""
    for target in target_positions:
